const ONE_PIXEL_PNG_BASE64 =
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=';

const ONE_PIXEL_JPEG_BASE64 =
  '';

const ONE_PIXEL_GIF_BASE64 = 'R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==';

function decodeBase64(value: string): ArrayBuffer {
  return Uint8Array.from(Buffer.from(value, 'base64')).buffer;
}

export function onePixelPng(): ArrayBuffer {
  return decodeBase64(ONE_PIXEL_PNG_BASE64);
}

export function onePixelJpeg(): ArrayBuffer {
  return decodeBase64(ONE_PIXEL_JPEG_BASE64);
}

export function onePixelGif(): ArrayBuffer {
  return decodeBase64(ONE_PIXEL_GIF_BASE64);
}
